import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Factory, Plus, Radio, UserCheck, Sun, Moon, LogOut, ChevronDown } from 'lucide-react';

const HeaderBar = ({ selectedPlant = 'All', onPlantChange, theme = 'light', onToggleTheme, user, onLogout }) => {
  const navigate = useNavigate();
  const [showDropdown, setShowDropdown] = useState(false);

  const currentUser = user || { name: 'Anita Desai', role: 'Shift Engineer', email: 'engineer@textwin.ai' };

  return (
    <header className="header-bar">
      <div className="header-left">
        <div className="plant-selector-group">
          <Factory size={18} style={{ color: 'var(--accent-primary)' }} />
          <span style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', fontWeight: '600' }}>Factory Context:</span>
          <select
            className="header-plant-select"
            value={selectedPlant}
            onChange={(e) => onPlantChange && onPlantChange(e.target.value)}
          >
            <option value="All">All Factory Plants</option>
            <option value="TexTwin Primary Mill">Coimbatore Primary Mill (Unit A)</option>
            <option value="TexTwin Secondary Mill">Tirupur Facility (Unit B)</option>
          </select>
        </div>
      </div>

      <div className="header-right">
        {/* Theme Switcher Button */}
        <button
          className="theme-toggle-btn"
          onClick={onToggleTheme}
          title={theme === 'light' ? 'Switch to Dark Theme' : 'Switch to White/Light Theme'}
        >
          {theme === 'light' ? <Moon size={18} /> : <Sun size={18} />}
        </button>

        <div className="live-status-pill">
          <Radio size={14} className="dot" style={{ color: 'var(--status-running)' }} />
          <span>SSE LIVE STREAM</span>
        </div>

        <button className="btn btn-primary btn-sm" onClick={() => navigate('/assets/new')}>
          <Plus size={16} /> Add Asset
        </button>

        {/* User Profile Dropdown */}
        <div style={{ position: 'relative' }}>
          <div className="user-profile-badge" onClick={() => setShowDropdown(!showDropdown)}>
            <div className="avatar">
              <UserCheck size={18} />
            </div>
            <div className="user-info">
              <span className="user-name">{currentUser.name}</span>
              <span className="user-role">{currentUser.role}</span>
            </div>
            <ChevronDown size={14} style={{ color: 'var(--text-muted)' }} />
          </div>

          {showDropdown && (
            <div
              className="glass-card"
              style={{
                position: 'absolute',
                right: 0,
                top: '50px',
                width: '200px',
                padding: '0.5rem',
                zIndex: 300,
                boxShadow: '0 10px 25px rgba(0,0,0,0.15)',
              }}
            >
              <div style={{ padding: '0.5rem 0.75rem', borderBottom: '1px solid var(--border-subtle)', marginBottom: '0.4rem' }}>
                <div style={{ fontSize: '0.82rem', fontWeight: '700', color: 'var(--text-primary)' }}>{currentUser.name}</div>
                <div style={{ fontSize: '0.73rem', color: 'var(--text-muted)' }}>{currentUser.email}</div>
              </div>

              <button
                onClick={() => {
                  setShowDropdown(false);
                  onLogout && onLogout();
                }}
                style={{
                  width: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                  padding: '0.5rem 0.75rem',
                  background: 'none',
                  border: 'none',
                  borderRadius: 'var(--radius-sm)',
                  color: 'var(--status-maintenance)',
                  fontSize: '0.85rem',
                  fontWeight: '600',
                  cursor: 'pointer',
                  textAlign: 'left',
                }}
              >
                <LogOut size={16} /> Sign Out
              </button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
};

export default HeaderBar;
